using System.CommandLine;
using System.Text;

namespace DevCli.Commands;

/// <summary>
/// Shell-completion generator (v0.1.0): walks the live System.CommandLine
/// tree so completions can never go stale, then emits static scripts for
/// PowerShell / bash / zsh. Static (not a dynamic completer protocol) on
/// purpose: zero runtime deps, works in locked-down shells, regenerated by
/// `deco completions` whenever commands change. Pure and tested.
/// </summary>
public static class CompletionsService
{
    public sealed record Entry(string Path, string Description, IReadOnlyList<string> Options);

    /// <summary>Flattens the command tree: "store portal-auth" etc. with option names.</summary>
    public static IReadOnlyList<Entry> BuildEntries(Command root)
    {
        var out_ = new List<Entry>();
        Walk(root, string.Empty, out_);
        return out_;
    }

    private static void Walk(Command cmd, string path, List<Entry> out_)
    {
        if (path.Length > 0)
        {
            var options = cmd.Options.Select(o => "--" + o.Name.TrimStart('-')).ToList();
            out_.Add(new Entry(path, cmd.Description ?? string.Empty, options));
        }

        foreach (Command sub in cmd.Subcommands)
        {
            Walk(sub, path.Length == 0 ? sub.Name : path + " " + sub.Name, out_);
        }
    }

    public static string Emit(string shell, string toolName, IReadOnlyList<Entry> entries) =>
        shell.ToLowerInvariant() switch
        {
            "powershell" or "pwsh" => EmitPowerShell(toolName, entries),
            "bash" => EmitBash(toolName, entries),
            "zsh" => EmitZsh(toolName, entries),
            _ => throw new Core.DecoException(
                $"Unknown shell '{shell}' (powershell|bash|zsh).", "completions-shell",
                Core.ExitCodes.UsageOrAuthNeeded),
        };

    private static string EmitPowerShell(string tool, IReadOnlyList<Entry> entries)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"# Generated by `{tool} completions --shell powershell` — re-run after upgrading {tool}.");
        sb.AppendLine($"Register-ArgumentCompleter -Native -CommandName {tool} -ScriptBlock {{");
        sb.AppendLine("    param($wordToComplete, $commandAst, $cursorPosition)");
        var paths = entries.Select(e => e.Path).Distinct().OrderBy(p => p).ToList();
        sb.Append("    $cmds = @(");
        sb.Append(string.Join(", ", paths.Select(p => $"'{tool} {p}'")));
        sb.AppendLine(")");
        sb.AppendLine("    $cmds | Where-Object { $_ -like \"*$wordToComplete*\" } | ForEach-Object {");
        sb.AppendLine("        [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_) }");
        sb.AppendLine("}");
        return sb.ToString();
    }

    private static string EmitBash(string tool, IReadOnlyList<Entry> entries)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"# Generated by `{tool} completions --shell bash` — source from ~/.bashrc.");
        sb.AppendLine($"_{tool}_complete() {{");
        sb.AppendLine("    local cur cmds opts");
        sb.AppendLine("    cur=\"${COMP_WORDS[COMP_CWORD]}\"");
        var top = entries.Where(e => !e.Path.Contains(' '))
            .Select(e => e.Path).Distinct().OrderBy(p => p);
        sb.AppendLine($"    cmds=\"{string.Join(" ", top)}\"");
        sb.AppendLine("    if [[ $COMP_CWORD -eq 1 ]]; then");
        sb.AppendLine("        COMPREPLY=($(compgen -W \"$cmds\" -- \"$cur\"))");
        sb.AppendLine("        return 0");
        sb.AppendLine("    fi");
        foreach (Entry e in entries.OrderBy(e => e.Path))
        {
            if (e.Options.Count == 0)
            {
                continue;
            }

            sb.AppendLine($"    if [[ \"${{COMP_WORDS[*]:0:$COMP_CWORD}}\" == \"{tool} {e.Path}\"* ]]; then");
            sb.AppendLine($"        opts=\"{string.Join(" ", e.Options)}\"");
            sb.AppendLine("        COMPREPLY=($(compgen -W \"$opts\" -- \"$cur\"))");
            sb.AppendLine("        return 0");
            sb.AppendLine("    fi");
        }

        sb.AppendLine("}");
        sb.AppendLine($"complete -F _{tool}_complete {tool}");
        return sb.ToString();
    }

    private static string EmitZsh(string tool, IReadOnlyList<Entry> entries)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"# Generated by `{tool} completions --shell zsh` — drop into fpath as _{tool}.");
        sb.AppendLine($"#compdef {tool}");
        sb.AppendLine($"_{tool}() {{");
        sb.AppendLine("    local -a cmds");
        sb.AppendLine("    cmds=(");
        foreach (Entry e in entries.OrderBy(e => e.Path))
        {
            string desc = e.Description.Replace("'", "'\\''", StringComparison.Ordinal);
            if (desc.Length > 80)
            {
                desc = desc[..80];
            }

            sb.AppendLine($"        '{e.Path}:{desc}'");
        }

        sb.AppendLine("    )");
        sb.AppendLine("    _describe 'command' cmds");
        sb.AppendLine("}");
        return sb.ToString();
    }
}
